type EnrichmentRecord = { id: string, tx_id: string, source: EnrichmentSource, found: EnrichmentData, status: EnrichmentStatus, created_at: string, };

type EnrichmentSource = { "explorer": Chain } | "token_list";

type EnrichmentStatus = "pending" | "applied" | "rejected";

/**
 * Make sure the FX cache has a rate of each currency for a day, fetching from
 * the public sources (and earlier days) what it lacks.
 */
type EnsureFxInput = { 
/**
 * Lowercase codes; USD and unknown codes are ignored.
 */
currencies: Array<string>, 
/**
 * `YYYY-MM-DD` (UTC); empty or absent means today.
 */
date: string | null, };

type EnsureFxOutput = { 
/**
 * Rates fetched just now; a point's `ts` is the day its source had, which
 * may be before the day asked for.
 */
points: Array<FxPoint>, 
/**
 * Currencies no source had within the look-back window.
 */
missing: Array<string>, };

/**
 * The head of an entity's card and what is linked to it.
 */
type EntityCard = { target: EntityRef, 
/**
 * Empty when the frontend names it (a built-in category, a budget).
 */
title: string, 
/**
 * The main number: a wallet's value, a goal's target, a limit.
 */
value: Amount | null, currency: string | null, archived: boolean, 
/**
 * Nothing with this id: deleted, or a link from another vault.
 */
missing: boolean, groups: Array<RelationGroup>, 
/**
 * The operation itself, for a `tx` card.
 */
transaction?: Transaction, };

/**
 * A kind of thing the app can open a card of.
 */
type EntityKind = "store" | "tx" | "category" | "contact" | "goal" | "budget" | "automation" | "workflow" | "reminder" | "alert" | "asset" | "scenario";

/**
 * The address of one entity: what the `?open=kind:id` link carries.
 */
type EntityRef = { kind: EntityKind, id: string, };

/**
 * An envelope: a named, earmarked part of one asset's balance in one store
 * («отпуск», «налоги»). Nothing physically moves — the store still holds the
 * money; envelopes only mark how much of it is spoken for.
 */
type Envelope = { id: string, store_id: string, name: string, asset: AssetRef, 
/**
 * How much is earmarked now, in `asset`.
 */
allocated: Amount, 
/**
 * What the envelope is filling up to, in `asset`.
 */
target: Amount | null, 
/**
 * A goal whose progress is this envelope.
 */
goal_id: string | null, created_at: string, };

/**
 * What creating or editing an envelope takes.
 */
type EnvelopeDraft = { store_id: string, name: string, asset: AssetRef, target: Amount | null, goal_id: string | null, };

/**
 * An envelope with what its store can still give it.
 */
type EnvelopeView = { envelope: Envelope, 
/**
 * Balance of the asset in the store not earmarked by any envelope; may
 * be negative when spending ate into the envelopes.
 */
free: Amount, 
/**
 * `allocated / target` in percent, when there is a target.
 */
pct: number | null, 
/**
 * The store holds less than its envelopes earmark.
 */
short: boolean, };

/**
 * A Bybit account (`FUND`, `UNIFIED`, `EARN`) and the sub-account standing for it.
 */
type ExchangeAccountBalance = { account: string, 
/**
 * `None` when the wallet has no sub-account of that kind yet.
 */
store_id: string | null, rows: Array<ExchangeCoinRow>, };

/**
 * One coin of one exchange account: the exchange's figure next to the ledger's.
 */
type ExchangeCoinRow = { coin: string, exchange: Amount, ledger: Amount, 
/**
 * `exchange − ledger`: what imports have not explained yet.
 */
diff: Amount, };

/**
 * Whether a key is stored. The secret is never part of this response.
 */
type ExchangeKeyStatus = { configured: boolean, 
/**
 * Masked identifier such as `abcd…wxyz`, for the settings screen.
 */
hint: string | null, 
/**
 * Sub-account spot fills are booked on; `None` = the key's own store.
 */
spot_store_id: string | null, 
/**
 * Sub-account futures fills are booked on; `None` = the key's own store.
 */
futures_store_id: string | null, };

/**
 * The exchange a wallet stands for, plus its terminal. Keys are kept apart in
 * `VaultDoc.exchange_keys` so secrets never travel with the store.
 */
type ExchangeProfile = { provider: ExchangeProvider, 
/**
 * Background import interval; 0 = off.
 */
import_interval_sec: number, terminal: TerminalState, 
/**
 * What an import brings in and where it books it.
 */
import: ImportSettings, };

type ExchangeProvider = "bybit" | "binance" | "okx";

type ExchangeProviderInfo = { provider: ExchangeProvider, 
/**
 * The app can connect to it; others are shown as «soon».
 */
supported: boolean, };

/**
 * Input to save a copy of a vault file elsewhere.
 */
